  /* 像素地圖：同一份開源圖資，換可愛色盤、用較低解析度畫再放大，海面有小波浪。 */
  const GAME_PR = 0.5;
  const GAME_COLORS = [[/^background$/, 'background-color', '#c8e6a0'], [/^landuse/, 'fill-color', '#bfe09a'], [/^(park|landcover)/, 'fill-color', '#9fd27f'],
    [/^water/, 'fill-color', '#8fcfd8'], [/^waterway/, 'line-color', '#8fcfd8'], [/^(building|aeroway)/, 'fill-color', '#f3d2b0'],
    [/casing/, 'line-color', '#d4b07e'], [/^(highway|road|tunnel|bridge)/, 'line-color', '#fff6d5'], [/^railway/, 'line-color', '#9b7b5a'], [/^boundary/, 'line-color', '#ffffff']];
  const scaleSize = (v, k) => typeof v === 'number' ? v * k : v && Array.isArray(v.stops) ? Object.assign({}, v, { stops: v.stops.map(([z, s]) => [z, s * k]) })
    : Array.isArray(v) && v[0] === 'interpolate' ? v.map((x, i) => i >= 4 && i % 2 === 0 ? scaleSize(x, k) : x)
    : Array.isArray(v) && v[0] === 'step' ? v.map((x, i) => i === 2 || (i >= 4 && i % 2 === 0) ? scaleSize(x, k) : x) : v;
  function gameStyle() {
    if (!rawStyle) return null;
    const s = JSON.parse(JSON.stringify(rawStyle));
    s.layers.forEach(l => {
      const hit = GAME_COLORS.find(([r, prop]) => r.test(l.id) && prop.split('-')[0] === l.type); if (hit) l.paint = { ...l.paint, [hit[1]]: hit[2] };
      if (l.type === 'fill') l.paint = { ...l.paint, 'fill-antialias': false };
      if (l.id === 'water') l.paint = { ...l.paint, 'fill-pattern': 'smv3-wave' };
      if (l.type === 'symbol') {
        if (/poi|highway|road|housenumber|aerodrome|transportation|shield/.test(l.id)) { l.layout = { ...l.layout, visibility: 'none' }; return; }
        l.layout = { ...l.layout, 'text-field': ['coalesce', ['get', 'name:zh-Hant'], ['get', 'name:nonlatin'], ['get', 'name']], 'text-size': scaleSize(l.layout && l.layout['text-size'] != null ? l.layout['text-size'] : 16, 2) };
        l.paint = { ...l.paint, 'text-color': '#ffffff', 'text-halo-color': '#5b7a5a', 'text-halo-width': 2, 'text-halo-blur': 0 };
      }
    });
    return s;
  }
  function wave(gl) {
    if (gl.hasImage && gl.hasImage('smv3-wave')) return;
    const c = document.createElement('canvas'); c.width = c.height = 16; const x = c.getContext('2d');
    x.fillStyle = '#8fcfd8'; x.fillRect(0, 0, 16, 16); x.fillStyle = '#e9f7f7'; x.fillRect(2, 4, 4, 1); x.fillRect(10, 11, 4, 1);
    try { gl.addImage('smv3-wave', x.getImageData(0, 0, 16, 16)); } catch (e) {}
  }
  function mapLook() {
    if (!glLayer) return;
    try {
      const gl = glLayer.getMaplibreMap(); if (!gl) return;
      if (!gl.__smv3) { gl.__smv3 = 1; gl.on('styleimagemissing', e => { if (e.id === 'smv3-wave') wave(gl); }); }
      styleReady.then(normal => { const s = game ? gameStyle() : normal; if (s) gl.setStyle(s); });
      if (gl.setPixelRatio) gl.setPixelRatio(game ? GAME_PR : (window.devicePixelRatio || 1));
      setTimeout(() => { try { glLayer._update(); } catch (e) {} }, 50);
    } catch (e) {}
  }
  function setGame(on, quiet) {
    game = on; store('sunnuGame', on ? '1' : '0'); root.querySelector('.smv3-side').removeAttribute('style'); if (!on && mapFull) mapFullToggle(false);
    root.classList.toggle('smv3-game', on);
    $('smv3-game').setAttribute('aria-pressed', on); $('smv3-game').textContent = on ? '遊戲模式：開' : '遊戲模式';
    $('smv3-gamebar').hidden = !on;
    clearInterval(typeTimer); travelToken++; stopCam(); encClear(); arenaClose();
    if (on && mem.id && !mem.nick) setTimeout(() => memAskNick(), 600);
    if (on && !root.querySelector('.smv3-hero-girl')) root.querySelector('.smv3-cta').insertAdjacentHTML('afterend', '<img class="smv3-hero-girl" src="' + sprite('girl_wave') + '" alt="">');
    if (!on && walker) { walker.remove(); walker = null; }
    mapLook(); paintMarkers(); render(); dexShow();
    const p = places.find(x => x.id === selectedId);
    if (on) { here = p || null; if (p && map) setWalker(L.latLng(p.lat, p.lng), 'girl_wave'); if (!quiet) { SFX.on(); toast('<img src="' + sprite('girl_wave') + '" alt="">孫女出發！點地圖任何地方，她就會走過去', 3000); } }
  }
  $('smv3-game').onclick = () => { setGame(!game); if (game && phone()) mapFullToggle(true); };
  const soundLabel = () => { $('smv3-sound').setAttribute('aria-pressed', sound); $('smv3-sound').textContent = sound ? '音效開' : '音效關'; dockSound(); };
  $('smv3-sound').onclick = () => { sound = !sound; store('sunnuSound', sound ? '1' : '0'); soundLabel(); SFX.on(); };
  soundLabel();
  HOW['找訊號']={goal:'在黑影中找出訊號怪，連過三關',how:V2_GAMES['找訊號'].tip,tip:'訊號格越多越近；點錯扣 3 秒；電池影子可充電；閃光彈一關一次；長按回聲指方向。',gest:'swipe',demo:'移動手電筒 → 看訊號格 → 點出怪物'};
  HOW['排隊']={goal:'一格一格擠過馬路，走到店門口',how:V2_GAMES['排隊'].tip,tip:'被撞退一格；號碼牌擋一次、雨傘擋一次、珍奶跳兩格；掉洞回檢查點；積水會變慢；後段夜晚無安全島。',gest:'swipe',demo:'滑動或按箭頭 → 閃車 → 擠到店門口'};
  HOW['追車']={goal:'沿月台奔跑，抵達列車門上車',how:V2_GAMES['追車'].tip,tip:'副站長會攔指定跑道，踩黃色箭頭能衝刺。電腦上下鍵／W、S 閃躲，抵達車門自動上車。',gest:'swipe',demo:'上下閃躲 → 踩箭頭 → 跑到車門上車'};
  HOW['找營業']={goal:'點店搶到三份不同食物',how:V2_GAMES['找營業'].tip,tip:'點店後還要跑到門口！怪物先到就搶走，牠拿三份你就輸。',gest:'tap',demo:'最後一份 → 點店衝刺 → 搶贏接食物'};
  HOW['群怪']={goal:'30 秒內達到 3000 分',how:V2_GAMES['群怪'].tip,tip:'飛行不吸血，手影鎖定原位置後，點遠處躲避。電腦也可按 1～4。',gest:'tap',demo:'降落吸血 → 手影 → 點遠處逃！'};
  HOW['讓開拍照']={goal:'搶拍三個景點的孫女獨照',how:V2_GAMES['讓開拍照'].tip,tip:'孫女倒數後才擺好姿勢，綠框才能拍！壞照三張就輸。',gest:'tap',demo:'看鏡頭 → 等空檔 → 點快門'};
  HOW['記憶']={goal:'隨機三個冷門車站，三站全部在車門關上前衝出去才通關',how:V2_GAMES['記憶'].tip,tip:'左右換道、跳過行李、下滑鑽過行李架；撿珍奶按衝刺撞飛全部；連擊有倍率；終點被人牆擋住要狂點。每站有一種搗亂：掉落行李、水漬、緊急煞車。',gest:'swipe',demo:'換道 → 跳／滑 → 衝刺撞飛 → 擠進車門'};
  loadMonsterSwitches();
  memInit();
  try { const cached = localStorage.getItem('sunnuMapData'); if (cached) { const data = JSON.parse(cached); if (use(data)) applyContent(data.content); } } catch (e) {}
  update(false); if (game) setGame(true, true); initMap(); requestData();
  if(gameState.prison.phase)setTimeout(prisonOpen,1000);
  if ('IntersectionObserver' in window && !reduced()) {
    const io = new IntersectionObserver(entries => entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), { threshold: .12 });
    root.querySelectorAll('.smv3-stat, .smv3-filters, .smv3-story h2, .smv3-story-copy p, .smv3-shop-link, .smv3-data-note').forEach(el => { el.classList.add('smv3-rv'); io.observe(el); });
  }
